import{_ as o,a as e}from"./chunks/supabase_sql_editor.CT34AdHe.js";import{_ as a,o as r,c as n,a0 as i}from"./chunks/framework.akKRIpjQ.js";const m=JSON.parse('{"title":"06 · Cloud Sync (BYO Supabase · multi-device + photo backup)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-cloud-sync.md","filePath":"guide/06-cloud-sync.md"}'),s={name:"guide/06-cloud-sync.md"};function d(l,t,u,c,h,p){return r(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="_06-·-cloud-sync-byo-supabase-·-multi-device-photo-backup" tabindex="-1">06 · Cloud Sync (BYO Supabase · multi-device + photo backup) <a class="header-anchor" href="#_06-·-cloud-sync-byo-supabase-·-multi-device-photo-backup" aria-label="Permalink to &quot;06 · Cloud Sync (BYO Supabase · multi-device + photo backup)&quot;">​</a></h1><blockquote><p>The app ships in <strong>pure-local mode</strong> (no upload, no account). If you want multi-device sync + photo backup, spin up a free <a href="https://supabase.com" target="_blank" rel="noreferrer">Supabase</a> project (BYO model — your own project), paste URL + Anon Key into the login page. <strong>Entirely optional.</strong></p></blockquote><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Sign up at <a href="https://supabase.com" target="_blank" rel="noreferrer">supabase.com</a> → Dashboard → click <strong>&quot;New project&quot;</strong> to create a free-tier project.</li></ol><img src="'+o+'" alt="Supabase Dashboard — create new project" style="max-width:720px;border-radius:12px;margin:12px 0;"><ol start="2"><li>Once the project is ready, left menu → <strong>SQL Editor</strong> → <strong>+ New query</strong> → paste <code>schema.sql</code> (the App has a one-tap &quot;Copy schema.sql&quot; button) → click <strong>Run</strong>.</li></ol><img src="'+e+'" alt="Supabase SQL Editor — paste and run schema.sql" style="max-width:720px;border-radius:12px;margin:12px 0;"><ol start="3"><li><p>Back in the App, open &quot;Sign in / Sign up (cloud sync)&quot; → pick the <strong>&quot;Not yet configured&quot;</strong> branch (first time) → paste your Supabase <code>Project URL</code> + <code>anon public key</code> (from Project Settings → API) → Save.</p></li><li><p>Pick one of the three sign-in methods on the login page: email code / GitHub OAuth / Google OAuth → data starts syncing both directions.</p></li></ol><h2 id="_3-sign-in-methods-on-the-login-page" tabindex="-1">3 sign-in methods on the login page <a class="header-anchor" href="#_3-sign-in-methods-on-the-login-page" aria-label="Permalink to &quot;3 sign-in methods on the login page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Email code</strong></td><td>Zero-config; first time, or if you don&#39;t want OAuth</td></tr><tr><td><strong>GitHub OAuth</strong></td><td>Requires enabling GitHub provider in Supabase Dashboard</td></tr><tr><td><strong>Google OAuth</strong></td><td>Requires enabling Google provider in Supabase Dashboard</td></tr></tbody></table><h2 id="_3-sync-buttons-on-the-login-page" tabindex="-1">3 sync buttons on the login page <a class="header-anchor" href="#_3-sync-buttons-on-the-login-page" aria-label="Permalink to &quot;3 sync buttons on the login page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Behaviour</th><th>Risk</th></tr></thead><tbody><tr><td><strong>Sync now</strong></td><td>Bidirectional LWW merge; conflicts → copy (<code>id#c&lt;ms&gt;</code>, both kept)</td><td>None</td></tr><tr><td><strong>Restore from cloud</strong> ⚠️</td><td>Delete all local → pull all cloud</td><td>Local unsynced changes lost</td></tr><tr><td><strong>Push local to cloud</strong> ⚠️</td><td>Delete all cloud for your account → push local</td><td>Other devices&#39; cloud changes overwritten</td></tr></tbody></table><blockquote><p>The latter two first show an <strong>AlertDialog</strong> with &quot;Will delete N rows / M photos&quot; + red <strong>&quot;Confirm&quot;</strong> button.</p></blockquote><h2 id="pricing-quota" tabindex="-1">Pricing / quota <a class="header-anchor" href="#pricing-quota" aria-label="Permalink to &quot;Pricing / quota&quot;">​</a></h2><ul><li><strong>Free tier</strong>: DB 500 MB / Storage 1 GB / 50,000 MAU — way more than any individual&#39;s racquet + stringing + grip data needs</li><li>All data lives in <strong>your own</strong> Supabase project; AceCrush team can&#39;t see it; developer can&#39;t see it</li><li>To stop using: tap the &quot;Switch Supabase project&quot; icon top-right of the login page → double confirm → clears current session</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause / fix</th></tr></thead><tbody><tr><td>Probe says &quot;✗ Tables missing&quot;</td><td>Didn&#39;t run <code>schema.sql</code> or run failed → redo step 2</td></tr><tr><td>Probe says &quot;✗ Invalid anon key&quot;</td><td>Truncated when copying; recopy from Project Settings → API</td></tr><tr><td>GitHub / Google OAuth errors &quot;provider not enabled&quot;</td><td>Your self-built Supabase project doesn&#39;t have that provider enabled; enable in Dashboard or fall back to email code</td></tr><tr><td>Email login delivers a link instead of a 6-digit code</td><td>Dashboard → Authentication → Providers → Email → turn off &quot;Confirm email&quot;; Email Templates body must contain the token placeholder (rendered by Supabase as <code>&amp;#123;&amp;#123; .Token &amp;#125;&amp;#125;</code>)</td></tr><tr><td>Photos don&#39;t download (rows sync OK but photoDown = 0)</td><td>Use <strong>&quot;Restore from cloud&quot;</strong> for a hard re-pull</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./00-introduction.html">00 · Introduction</a></li><li><a href="./07-settings.html">07 · Settings</a></li><li><a href="./10-faq.html">10 · FAQ</a></li></ul>',19)])])}const q=a(s,[["render",d]]);export{m as __pageData,q as default};
